GD.dynasties = [
  {"n":"远古","full":"远古传说时代","start":-5000,"end":-2070,"capital":"（部落时代，无固定都城）","founder":"炎帝、黄帝（传说）","color":"#7a6a53","summary":"距今约170万年的元谋人是我国境内已知最早的古人类，北京人会使用天然火。约七千年前，河姆渡人种水稻、住干栏式房屋，半坡人种粟、住半地穴式房屋。传说炎帝、黄帝部落联合形成华夏族，尧、舜、禹以禅让方式传位。","events":["元谋人、北京人生活在中华大地","河姆渡人种植水稻，半坡人种植粟","炎黄联合，涿鹿之战打败蚩尤","尧舜禹禅让"],"people":["炎帝","黄帝","尧","舜","禹"],"culture":["磨制石器与彩陶","原始农业与家畜饲养","干栏式房屋","传说中的仓颉造字"],"fun":"北京人遗址在北京周口店龙骨山，距今约70万—20万年。北京人已经会使用天然火，还能长时间保存火种，这是人类进化史上的一大进步。"},
  {"n":"夏","full":"夏朝","start":-2070,"end":-1600,"capital":"阳城、斟鄩等","founder":"禹／启","color":"#6b8e5a","summary":"约公元前2070年，禹建立夏朝，这是我国历史上第一个王朝。禹死后儿子启继位，标志着世袭制代替了禅让制，“公天下”变成了“家天下”。夏朝最后一位王桀暴虐无道，约公元前1600年被商汤所灭。","events":["大禹治水","启建立夏朝，世袭制代替禅让制","夏桀暴政","鸣条之战，商汤灭夏"],"people":["禹","启","桀"],"culture":["二里头遗址的宫殿建筑","绿松石龙形器","早期青铜器"],"fun":"河南偃师二里头遗址被许多学者认为可能是夏朝晚期的都城。考古学家在这里发现了一条用两千多片绿松石拼成的“龙”，被称为“超级国宝”。"},
  {"n":"商","full":"商朝","start":-1600,"end":-1046,"capital":"亳，后迁殷（今河南安阳）","founder":"商汤","color":"#8a5a3c","summary":"约公元前1600年，商汤灭夏建立商朝。商王盘庚迁都到殷，此后统治稳定，所以商朝又称殷商。商朝青铜器铸造技术高超，还留下了成熟的文字——甲骨文。约公元前1046年，商纣王在牧野之战中失败，商朝灭亡。","events":["商汤灭夏建立商朝","盘庚迁殷","用甲骨占卜记事","牧野之战，商朝灭亡"],"people":["商汤","伊尹","盘庚","妇好","商纣王"],"culture":["甲骨文","后母戊鼎","四羊方尊","殷墟"],"fun":"相传1899年，学者王懿荣生病抓药，发现一味叫“龙骨”的中药上刻着奇怪的符号。原来这是三千多年前的甲骨文，“龙骨”其实是龟甲和兽骨。"},
  {"n":"西周","full":"西周","start":-1046,"end":-771,"capital":"镐京（今陕西西安附近）","founder":"周武王","color":"#5a6e8c","summary":"约公元前1046年，周武王灭商建立周朝，定都镐京，史称西周。为巩固统治，西周实行分封制，把土地和百姓分给王族、功臣等，让他们建立诸侯国。后来周厉王暴政引发国人暴动，公元前771年西周灭亡。","events":["牧野之战，武王灭商","实行分封制","周公辅政，制礼作乐","公元前841年国人暴动","公元前771年西周灭亡"],"people":["周文王","周武王","姜子牙","周公","周幽王"],"culture":["分封制与礼乐制度","青铜器铭文（金文）","《诗经》中的早期诗歌"],"fun":"公元前841年，国人暴动赶走了周厉王，这一年被称为“共和元年”。从这一年起，中国历史有了连续的确切纪年，一直延续到今天没有中断。"},
  {"n":"春秋","full":"春秋时期","start":-770,"end":-476,"capital":"洛邑（东周都城）","founder":"周平王（东迁）","color":"#7d5a8a","summary":"公元前770年，周平王迁都洛邑，东周开始，东周前期称为春秋时期。这时周王室衰微，诸侯争霸，齐桓公、晋文公、楚庄王等先后称霸，吴越争霸还留下了卧薪尝胆的故事。孔子、老子等思想家也生活在这个时代。","events":["平王东迁","齐桓公称霸","城濮之战，晋文公称霸","吴越争霸，卧薪尝胆"],"people":["齐桓公","管仲","晋文公","勾践","孔子"],"culture":["儒家与《论语》","道家与《道德经》","《孙子兵法》","铁农具和牛耕开始出现"],"fun":"“春秋”这个名字来自鲁国的编年体史书《春秋》，相传经过孔子整理。书中记载的年代和这一时期大体相当，于是人们就把这段历史叫作春秋时期。"},
  {"n":"战国","full":"战国时期","start":-475,"end":-221,"capital":"各国有自己的都城（东周都洛邑）","founder":"三家分晋、田氏代齐后七雄并立","color":"#8c4a4a","summary":"公元前475年起进入战国时期。经过兼并，形成齐、楚、燕、韩、赵、魏、秦“战国七雄”。各国纷纷变法图强，秦国经过商鞅变法后最为强大。这一时期思想活跃，出现“百家争鸣”。公元前221年秦统一六国，战国结束。","events":["战国七雄并立","商鞅变法","李冰主持修建都江堰","长平之战","百家争鸣"],"people":["商鞅","孟子","墨子","屈原","韩非"],"culture":["都江堰","曾侯乙编钟","司南","屈原与楚辞"],"fun":"“战国”这个名称来自西汉刘向编订的《战国策》。书中记录了谋士们游说各国的故事，“画蛇添足”“狐假虎威”等成语都出自这本书。"},
  {"n":"秦","full":"秦朝","start":-221,"end":-207,"capital":"咸阳","founder":"秦始皇（嬴政）","color":"#3f4a5a","summary":"公元前221年，秦王嬴政灭掉六国，建立我国历史上第一个统一的多民族的中央集权国家——秦朝。他统一文字、货币、度量衡，推行郡县制，修筑长城。但秦朝暴政严重，陈胜吴广起义后，公元前207年秦朝灭亡。","events":["公元前221年统一六国","统一文字、货币、度量衡","修筑万里长城","陈胜吴广起义","巨鹿之战"],"people":["秦始皇","李斯","蒙恬","陈胜","项羽"],"culture":["小篆","秦始皇陵兵马俑","万里长城","灵渠"],"fun":"“皇帝”这个称号是秦始皇创立的。他认为自己“德兼三皇，功过五帝”，便自称“始皇帝”，希望子孙传到万世。没想到秦朝只存在了短短15年。"},
  {"n":"西汉","full":"西汉","start":-202,"end":8,"capital":"长安","founder":"刘邦（汉高祖）","color":"#a0522d","summary":"楚汉之争后，刘邦于公元前202年建立汉朝，定都长安，史称西汉。汉初休养生息，出现“文景之治”。汉武帝时国力强盛，他派张骞出使西域，派卫青、霍去病北击匈奴。丝绸之路开通，中外交流日益频繁。","events":["刘邦建立西汉","文景之治","汉武帝“罢黜百家，独尊儒术”","张骞出使西域，开通丝绸之路","司马迁著《史记》"],"people":["刘邦","汉武帝","张骞","卫青","司马迁"],"culture":["丝绸之路","《史记》","长信宫灯","金缕玉衣"],"fun":"我们今天说的“汉族”“汉字”“汉语”里的“汉”，都和汉朝有关。两汉统治了四百多年，“汉”渐渐成了中华民族主体民族的名称。"},
  {"n":"东汉","full":"东汉","start":25,"end":220,"capital":"洛阳","founder":"刘秀（汉光武帝）","color":"#8b6d3a","summary":"公元25年，刘秀重建汉朝，定都洛阳，史称东汉。东汉前期出现“光武中兴”，班超经营西域。这一时期科技成就突出：蔡伦改进造纸术，张衡发明地动仪，张仲景、华佗成为名医。184年爆发黄巾起义，220年东汉灭亡。","events":["刘秀建立东汉","班超出使西域","蔡伦改进造纸术","张衡发明地动仪","黄巾起义"],"people":["刘秀","班超","蔡伦","张衡","张仲景"],"culture":["造纸术（蔡侯纸）","地动仪与浑天仪","《伤寒杂病论》","马踏飞燕"],"fun":"东汉时在洛阳修建的白马寺，被认为是中国第一座官办佛寺。相传当年用白马驮着佛经和佛像来到洛阳，所以取名“白马寺”。"},
  {"n":"三国","full":"三国时期","start":220,"end":280,"capital":"魏：洛阳；蜀：成都；吴：建业","founder":"曹丕、刘备、孙权","color":"#4a6b7c","summary":"东汉末年群雄割据。200年官渡之战，曹操统一北方；208年赤壁之战，孙刘联军大败曹军，奠定三国鼎立的基础。220年曹丕建魏，221年刘备建蜀，222年孙权建吴。263年魏灭蜀，280年西晋灭吴。","events":["官渡之战","赤壁之战","三国鼎立","诸葛亮北伐"],"people":["曹操","刘备","孙权","诸葛亮","关羽"],"culture":["诸葛亮《出师表》","建安文学（三曹诗文）","马钧改进翻车"],"fun":"小说里“草船借箭”的主角是诸葛亮，但据史书记载，真正“借箭”的是孙权：他乘船观察曹军，船的一侧中箭太多，就调转船头让另一侧受箭。"},
  {"n":"西晋","full":"西晋","start":266,"end":316,"capital":"洛阳","founder":"司马炎（晋武帝）","color":"#6a5a7a","summary":"266年，司马炎夺取曹魏政权，建立晋朝，定都洛阳，史称西晋。280年西晋灭吴，结束了三国分裂局面。但西晋统治者生活奢侈，统治集团内部爆发“八王之乱”，北方各族纷纷起兵，316年西晋灭亡。","events":["司马炎建立西晋","280年灭吴统一全国","八王之乱","316年西晋灭亡"],"people":["司马炎","陈寿","左思","祖逖"],"culture":["陈寿《三国志》","左思《三都赋》","裴秀的地图学"],"fun":"西晋文学家左思写了一篇《三都赋》，人们争相传抄，洛阳的纸一下子供不应求，价格都涨了。这就是成语“洛阳纸贵”的由来。"},
  {"n":"东晋","full":"东晋十六国","start":317,"end":420,"capital":"建康（今南京）","founder":"司马睿（晋元帝）","color":"#3f7466","summary":"317年，司马睿在建康重建晋朝，史称东晋。同时北方先后出现多个政权，史称“十六国”。383年淝水之战，东晋以少胜多打败前秦，保住了江南。北方人口大量南迁，带来了技术和劳动力，江南得到开发。","events":["司马睿建立东晋","北方十六国并立","淝水之战","北方人民南迁，江南开发"],"people":["司马睿","谢安","王羲之","顾恺之","陶渊明"],"culture":["王羲之《兰亭集序》","顾恺之《洛神赋图》","陶渊明田园诗","敦煌莫高窟开始开凿"],"fun":"淝水之战中，前秦君主苻坚望见八公山上的草木，以为都是晋兵；战败逃跑时，听到风声和鹤叫也以为是追兵。“草木皆兵”“风声鹤唳”就来自这里。"},
  {"n":"南北朝","full":"南北朝","start":420,"end":589,"capital":"南朝：建康；北魏：平城，后迁洛阳","founder":"刘裕（南朝宋）、拓跋珪（北魏）","color":"#7a5c6e","summary":"420年刘裕建立宋，南方先后经历宋、齐、梁、陈四朝，史称南朝。北方由北魏统一，后来分裂演变为东魏、西魏、北齐、北周，史称北朝。北魏孝文帝迁都洛阳、推行汉化改革，促进了民族交融。589年隋灭陈，南北重归统一。","events":["北魏孝文帝迁都洛阳","孝文帝推行汉化改革","祖冲之精确计算圆周率","贾思勰著《齐民要术》"],"people":["北魏孝文帝","祖冲之","贾思勰","郦道元","刘裕"],"culture":["《齐民要术》","《水经注》","云冈石窟和龙门石窟","北朝民歌《木兰诗》"],"fun":"祖冲之算出圆周率在3.1415926和3.1415927之间，这个纪录保持了近一千年。为纪念他，月球背面的一座环形山和一颗小行星都以他的名字命名。"},
  {"n":"隋","full":"隋朝","start":581,"end":618,"capital":"大兴城（长安）","founder":"杨坚（隋文帝）","color":"#5e6b3a","summary":"581年杨坚建立隋朝，589年灭陈，结束了近三百年的分裂局面。隋文帝改革制度，社会经济繁荣。隋炀帝开通大运河，设立进士科，科举制正式诞生。但他滥用民力，引发隋末农民起义，618年隋朝灭亡。","events":["581年隋朝建立","589年隋灭陈，统一全国","开通大运河","科举制诞生","隋末农民起义"],"people":["隋文帝","隋炀帝","李春"],"culture":["大运河","赵州桥","科举制"],"fun":"隋朝只存在了37年，却留下两项了不起的工程：连通南北的大运河，和一千四百多年后依然屹立的赵州桥。赵州桥由工匠李春主持设计建造。"},
  {"n":"唐","full":"唐朝","start":618,"end":907,"capital":"长安","founder":"李渊（唐高祖）","color":"#a8563a","summary":"618年李渊建立唐朝，定都长安。唐太宗时出现“贞观之治”，唐玄宗前期出现“开元盛世”，唐朝成为当时世界上最强盛的国家之一。唐朝对外交往频繁，诗歌空前繁荣。755年安史之乱后唐朝由盛转衰，907年灭亡。","events":["贞观之治","文成公主入藏","武则天称帝","开元盛世","安史之乱"],"people":["唐太宗","武则天","唐玄宗","李白","杜甫"],"culture":["唐诗","雕版印刷《金刚经》","唐三彩","火药的发明"],"fun":"唐朝长安城面积约84平方千米，是当时世界上最大的城市之一。城里有东市、西市两大市场，相传“买东西”这个说法就和它们有关。"},
  {"n":"五代十国","full":"五代十国","start":907,"end":960,"capital":"开封、洛阳等","founder":"朱温（后梁）","color":"#5c5f73","summary":"907年朱温灭唐，建立后梁。此后中原先后出现后梁、后唐、后晋、后汉、后周五个朝代，史称“五代”；南方等地先后出现吴、南唐、吴越、前蜀等十个政权，合称“十国”。960年赵匡胤建立北宋，逐步结束分裂。","events":["907年朱温灭唐建立后梁","五代频繁更替","后晋割让燕云十六州给契丹","后周世宗改革"],"people":["朱温","石敬瑭","柴荣","李煜"],"culture":["南唐后主李煜的词","雕版印刷儒家经典","《韩熙载夜宴图》"],"fun":"五代前后只有约53年，却换了五个朝代，其中最短的后汉只存在了约4年。这一时期政权更替频繁，老百姓饱受战乱之苦。"},
  {"n":"北宋","full":"北宋","start":960,"end":1127,"capital":"东京（开封）","founder":"赵匡胤（宋太祖）","color":"#3a6e8f","summary":"960年赵匡胤发动陈桥兵变，建立北宋，定都东京开封。北宋加强中央集权、重文轻武，经济文化高度繁荣。北宋与契丹建立的辽订立澶渊之盟，又与西夏对峙。范仲淹、王安石先后推行改革。1127年金军攻破开封，北宋灭亡。","events":["陈桥兵变","杯酒释兵权","澶渊之盟","王安石变法","靖康之变"],"people":["赵匡胤","范仲淹","王安石","包拯","苏轼"],"culture":["毕昇发明活字印刷术","指南针用于航海","《清明上河图》","交子"],"fun":"北宋时四川地区出现了“交子”，这是世界上最早的纸币。当时四川用铁钱，又重又不方便携带，商人们就想出了用纸做的“交子”来代替。"},
  {"n":"南宋","full":"南宋","start":1127,"end":1279,"capital":"临安（今杭州）","founder":"赵构（宋高宗）","color":"#4f7f6f","summary":"1127年赵构重建宋朝，后定都临安，史称南宋。两宋时期，北方先后有契丹建立的辽、党项建立的西夏、女真建立的金等政权。金灭辽和北宋后与南宋对峙，岳飞等人英勇抗金。南宋时经济重心南移完成，1279年南宋被元所灭。","events":["岳飞抗金，郾城大捷","宋金绍兴和议","经济重心南移完成","文天祥抗元","崖山海战，南宋灭亡"],"people":["宋高宗","岳飞","陆游","辛弃疾","文天祥"],"culture":["宋词","朱熹理学","海上贸易繁荣","瓷器远销海外"],"fun":"南宋时流传着“苏湖熟，天下足”的谚语，意思是苏州、湖州一带丰收了，全国的粮食就够吃了。这说明江南已成为全国最重要的粮仓。"},
  {"n":"元","full":"元朝","start":1271,"end":1368,"capital":"大都（今北京）","founder":"忽必烈（元世祖）","color":"#7b4b2a","summary":"1206年铁木真统一蒙古，被尊为成吉思汗。1271年忽必烈定国号为元，次年定都大都，1279年完成统一。元朝实行行省制度，设宣政院管辖西藏，设澎湖巡检司管辖澎湖和琉球（今台湾）。1368年元朝在大都的统治被推翻。","events":["成吉思汗统一蒙古","忽必烈建立元朝","实行行省制度","马可·波罗来华","郭守敬编订《授时历》"],"people":["成吉思汗","忽必烈","郭守敬","关汉卿","黄道婆"],"culture":["元曲《窦娥冤》","《授时历》","黄道婆改进棉纺织技术"],"fun":"今天“河北省”“河南省”里的“省”，起源于元朝的行省制度。元朝在地方设立行中书省，简称“行省”，这一制度一直影响到今天。"},
  {"n":"明","full":"明朝","start":1368,"end":1644,"capital":"南京，后迁北京","founder":"朱元璋（明太祖）","color":"#9e3b3b","summary":"1368年朱元璋在南京建立明朝。明成祖朱棣迁都北京，派郑和七下西洋。明朝废除丞相、设立锦衣卫，加强皇权；戚继光抗击倭寇，保卫东南沿海。明朝后期政治腐败，1644年李自成攻入北京，明朝灭亡。","events":["朱元璋建立明朝","明成祖迁都北京","郑和下西洋","戚继光抗倭","李自成攻入北京"],"people":["朱元璋","明成祖","郑和","戚继光","李时珍"],"culture":["《本草纲目》","《天工开物》","故宫与明长城","《西游记》等古典小说"],"fun":"故宫又叫紫禁城，1420年建成。民间传说故宫有“9999间半”房屋，实际统计约有8700多间。它是世界上现存规模最大、保存最完整的木结构宫殿建筑群。"},
  {"n":"清","full":"清朝","start":1636,"end":1912,"capital":"盛京（沈阳），1644年后迁都北京","founder":"努尔哈赤（后金）、皇太极（改国号清）","color":"#86702a","summary":"1616年努尔哈赤建立后金，1636年皇太极改国号为清，1644年清军入关定都北京。康熙、雍正、乾隆时期出现“康乾盛世”，奠定了中国的基本版图。1840年鸦片战争后，中国逐渐沦为半殖民地半封建社会。1912年清帝退位。","events":["1644年清军入关","郑成功收复台湾","雅克萨之战与《尼布楚条约》","鸦片战争","辛亥革命"],"people":["康熙","乾隆","郑成功","林则徐","孙中山"],"culture":["《红楼梦》","京剧形成","《四库全书》","京张铁路"],"fun":"1790年，为给乾隆皇帝祝寿，四大徽班陆续进京演出。后来徽调与汉调等融合，逐渐形成了京剧。京剧被称为“国粹”，2010年列入人类非物质文化遗产代表作名录。"}
];
GD.figures = [
  {"n":"黄帝","d":"远古","role":"部落首领","clues":["相传我的妻子嫘祖教会人们养蚕缫丝。","传说造车、造船、仓颉造字等发明都和我的部落有关。","我曾联合炎帝，在涿鹿之战中打败了蚩尤。","我是“炎黄子孙”中的“黄”，号轩辕氏，被尊为“人文初祖”。"],"bio":"黄帝是传说中中原地区的部落联盟首领，号轩辕氏。相传他与炎帝联合，在涿鹿打败蚩尤，后来炎黄部落融合，逐渐形成华夏族。传说中造字、养蚕、造车等发明都和他有关，因此被尊为“人文初祖”。","quote":""},
  {"n":"大禹","d":"夏","role":"治水英雄","clues":["我的父亲用“堵”的办法治水，九年没有成功。","我改用疏导的办法，开挖河道，把洪水引入大海。","我治水十三年，三过家门而不入。","舜把首领之位禅让给我，我的儿子启后来建立了夏朝。"],"bio":"禹是传说中的部落联盟首领，鲧的儿子。他吸取父亲用堵塞法治水失败的教训，改用疏导的方法，治水十三年，三过家门而不入，终于平息水患。舜把首领之位禅让给他。禹死后，儿子启继位，世袭制代替了禅让制。","quote":"三过家门而不入"},
  {"n":"商汤","d":"商","role":"君主","clues":["相传我在洗澡的铜盘上刻着“苟日新，日日新，又日新”来提醒自己。","我任用贤臣伊尹，国力日渐强大。","我起兵讨伐暴虐的夏桀，在鸣条之战中打败了他。","我灭掉夏朝，大约在公元前1600年建立了商朝。"],"bio":"商汤是商朝的建立者。他任用伊尹等贤臣，关心百姓疾苦，使商部落日益强大。约公元前1600年，他起兵讨伐暴君夏桀，在鸣条之战中获胜，灭掉夏朝，建立了商朝。","quote":"苟日新，日日新，又日新。"},
  {"n":"周武王","d":"西周","role":"君主","clues":["我的父亲是周文王，他曾亲自请姜太公出山。","我在孟津与各路诸侯会盟，准备讨伐暴君。","约公元前1046年，我在牧野之战中打败了商纣王。","我建立了西周，定都镐京，并实行分封制。"],"bio":"周武王姬发是西周的建立者。他继承父亲周文王的事业，重用姜尚、周公等人。约公元前1046年，他联合各部落在牧野之战中大败商军，商纣王自焚，商朝灭亡。武王建立西周，定都镐京，实行分封制。","quote":""},
  {"n":"姜子牙","d":"西周","role":"军事家","clues":["传说我年纪很大时还在渭水边用直钩钓鱼。","有句歇后语“……钓鱼——愿者上钩”，说的就是我。","我辅佐周文王和周武王，帮助周灭掉了商朝。","我又叫姜尚、姜太公，后来被封到齐国。"],"bio":"姜子牙名尚，又称姜太公、太公望，是商末周初的政治家、军事家。相传他晚年在渭水边垂钓，被周文王请去辅佐。他协助周武王在牧野之战中灭商，立下大功，后来被封于齐，成为齐国的始祖。","quote":"太公钓鱼，愿者上钩。"},
  {"n":"孔子","d":"春秋","role":"思想家","clues":["我曾带着学生周游列国十几年，宣传自己的主张。","我主张“有教无类”，相传有弟子三千、贤人七十二。","我是儒家学派的创始人，思想的核心是“仁”。","学生们把我的言行记录在《论语》里，我被尊为“至圣先师”。"],"bio":"孔子名丘，字仲尼，春秋末期鲁国人，是伟大的思想家、教育家，儒家学派创始人。他提出“仁”的学说，主张“为政以德”；他创办私学，主张有教无类、因材施教。他的言行由弟子整理成《论语》。","quote":"学而时习之，不亦说乎？"},
  {"n":"老子","d":"春秋","role":"思想家","clues":["相传我曾在东周担任管理藏书的官员。","传说我骑着青牛西出函谷关，留下一本五千多字的书。","我认为事物都有对立面，还会相互转化，比如“祸兮福之所倚”。","我是道家学派的创始人，写了《道德经》。"],"bio":"老子姓李名耳，春秋时期思想家，道家学派创始人。他的著作《道德经》约五千字，认为一切事物都有对立的两面，并且可以互相转化，主张“无为而治”。他的思想对中国文化影响深远。","quote":"千里之行，始于足下。"},
  {"n":"孙子","d":"春秋","role":"军事家","clues":["我原本是齐国人，后来到吴国帮助吴王训练军队。","我写的兵书共十三篇，被翻译成多种文字流传世界。","“知彼知己，百战不殆”就出自我的兵书。","我叫孙武，被后人尊为“兵圣”。"],"bio":"孙子名武，春秋末期齐国人，著名军事家，被尊为“兵圣”。他到吴国辅佐吴王阖闾，使吴国强盛起来。他所著的《孙子兵法》共十三篇，是我国现存最早的兵书，被誉为“兵学圣典”，至今仍在世界各地被研究。","quote":"知彼知己，百战不殆。"},
  {"n":"墨子","d":"战国","role":"思想家","clues":["我出身平民，精通木工和机械制造。","我曾走了十天十夜赶到楚国，劝阻楚国攻打宋国。","我主张“兼爱”“非攻”，反对不义的战争。","我是墨家学派的创始人，我国第一颗量子科学实验卫星以我的名字命名。"],"bio":"墨子名翟，战国初期思想家，墨家学派创始人。他代表平民的利益，主张“兼爱”“非攻”“尚贤”“节用”。《墨经》中还记载了小孔成像等光学知识。2016年我国发射的世界首颗量子科学实验卫星被命名为“墨子号”。","quote":"兼相爱，交相利。"},
  {"n":"屈原","d":"战国","role":"文学家","clues":["我曾在楚国做官，主张联合齐国对抗秦国。","我遭到排挤被流放，写下了长诗《离骚》。","楚国都城被秦军攻破后，我悲愤地投汨罗江而死。","人们在端午节吃粽子、赛龙舟来纪念我。"],"bio":"屈原是战国时期楚国的诗人、政治家。他主张改革政治、联齐抗秦，却遭到排挤而被流放。他创作了《离骚》《天问》《九歌》等作品，开创了“楚辞”这种诗体。楚国郢都被秦军攻破后，他投汨罗江而死。","quote":"路漫漫其修远兮，吾将上下而求索。"},
  {"n":"秦始皇","d":"秦","role":"皇帝","clues":["我十三岁就当上了国君。","我统一了文字、货币和度量衡。","我觉得自己“德兼三皇，功过五帝”，于是创立了一个新的称号。","公元前221年，我灭掉六国，建立了中国历史上第一个统一的中央集权国家。"],"bio":"秦始皇嬴政13岁继承秦王位。公元前230年至前221年，他先后灭掉韩、赵、魏、楚、燕、齐六国，建立秦朝，自称“始皇帝”。他统一文字、货币、度量衡，推行郡县制，修筑长城，影响深远，但暴政也加重了百姓负担。","quote":""},
  {"n":"陈胜","d":"秦","role":"起义领袖","clues":["我年轻时给人当雇农，曾感叹“燕雀安知鸿鹄之志哉”。","我和伙伴被征发去渔阳戍边，途中遇大雨误了期限。","我在大泽乡发动起义，喊出“王侯将相宁有种乎”。","我和吴广领导了中国历史上第一次大规模农民起义。"],"bio":"陈胜字涉，秦末农民起义领袖。公元前209年，他和吴广等九百多人被征发去渔阳戍边，因大雨误期，按秦法要被处死，于是在大泽乡起义，建立“张楚”政权。起义虽然失败，却沉重打击了秦朝的统治。","quote":"燕雀安知鸿鹄之志哉！"},
  {"n":"项羽","d":"秦","role":"军事家","clues":["我是楚国名将项燕的后代，力气大到能举起大鼎。","在巨鹿之战中，我下令“破釜沉舟”，大败秦军主力。","我自称“西楚霸王”，和刘邦争夺天下。","垓下被围时我听到“四面楚歌”，最后在乌江边自刎。"],"bio":"项羽名籍，字羽，出身楚国贵族，是秦末杰出的军事家。巨鹿之战中他破釜沉舟，大败秦军主力。秦亡后他自立为“西楚霸王”，与刘邦进行了长达四年的楚汉之争，最终在垓下被围，突围到乌江边自刎。","quote":"力拔山兮气盖世。"},
  {"n":"刘邦","d":"西汉","role":"皇帝","clues":["我曾是秦朝的一名亭长。","我率先攻入咸阳，与关中百姓“约法三章”。","我与项羽进行了四年的楚汉之争，最后在垓下取得胜利。","公元前202年我建立了汉朝，被称为汉高祖。"],"bio":"刘邦是沛县人，秦朝时任泗水亭长。秦末他起兵反秦，率先攻入咸阳，与关中百姓约法三章。后来经过楚汉之争打败项羽，于公元前202年建立汉朝，史称西汉，定都长安。他实行休养生息的政策，稳定了社会。","quote":"大风起兮云飞扬。"},
  {"n":"张骞","d":"西汉","role":"外交家","clues":["我出使途中被匈奴扣留了十多年，却始终没有忘记使命。","我先后两次出使西域，第一次在公元前138年出发。","我的出使被史书称为“凿空”之旅。","汉武帝派我出使西域，为丝绸之路的开通奠定了基础。"],"bio":"张骞是西汉外交家。公元前138年，他奉汉武帝之命出使西域，途中被匈奴扣留十余年，逃脱后继续西行，历尽艰险回到长安。公元前119年他第二次出使西域。他的出使加强了汉朝与西域的联系，为丝绸之路的开通奠定了基础。","quote":""},
  {"n":"司马迁","d":"西汉","role":"史学家","clues":["我年轻时游历了很多地方，搜集历史资料。","我遭受宫刑，却忍辱负重坚持完成著作。","鲁迅称赞我的书是“史家之绝唱，无韵之离骚”。","我写了我国第一部纪传体通史《史记》。"],"bio":"司马迁是西汉史学家、文学家。他继承父亲司马谈的遗志担任太史令，因替李陵辩解而受宫刑，但忍辱发愤，写成《史记》。《史记》记载了从黄帝到汉武帝时期约三千年的历史，是我国第一部纪传体通史。","quote":"人固有一死，或重于泰山，或轻于鸿毛。"},
  {"n":"汉武帝","d":"西汉","role":"皇帝","clues":["我使用了中国历史上第一个年号“建元”。","我采纳董仲舒的建议，“罢黜百家，独尊儒术”。","我派卫青、霍去病北击匈奴，派张骞出使西域。","我叫刘彻，人们常把我和秦始皇并称为“秦皇汉武”。"],"bio":"汉武帝刘彻是西汉的第七位皇帝。他推行“推恩令”削弱诸侯王势力，采纳董仲舒建议“罢黜百家，独尊儒术”，把铸币权收归中央，实行盐铁官营；又派卫青、霍去病大败匈奴，派张骞出使西域，使西汉进入鼎盛时期。","quote":""},
  {"n":"蔡伦","d":"东汉","role":"发明家","clues":["我是东汉的一名宦官，负责监督制造宫廷用品。","我用树皮、麻头、破布和旧渔网作原料。","我改进了造纸术，让纸变得又轻又便宜。","人们把我造的纸叫作“蔡侯纸”。"],"bio":"蔡伦是东汉宦官。他总结前人经验，用树皮、麻头、破布、旧渔网等原料改进造纸术，造出又轻又便宜的纸，105年献给汉和帝，人们称之为“蔡侯纸”。此后纸逐渐普及，成为主要的书写材料，后来传到世界各地。","quote":""},
  {"n":"张衡","d":"东汉","role":"科学家","clues":["我写的《二京赋》是很有名的文学作品。","我制作了浑天仪，用来演示天体的运行。","月球背面有一座环形山以我的名字命名。","我发明了地动仪，能测出发生地震的方向。"],"bio":"张衡是东汉著名科学家、文学家。他精通天文、数学，制作了浑天仪，132年又发明了候风地动仪，能测知地震发生的方向，比欧洲类似仪器早1700多年。月球上有一座环形山以他的名字命名。","quote":""},
  {"n":"华佗","d":"东汉","role":"医学家","clues":["我不愿做官，行医走遍了许多地方。","我模仿虎、鹿、熊、猿、鸟的动作，编了一套健身操。","我发明了“麻沸散”，让病人在手术时减轻痛苦。","我是东汉末年的名医，被称为“外科鼻祖”。"],"bio":"华佗是东汉末年著名医学家，精通内、外、妇、儿各科，尤其擅长外科。他发明了全身麻醉药“麻沸散”，为病人做腹部手术；还模仿五种动物的动作创编“五禽戏”，用来强身健体。","quote":""},
  {"n":"诸葛亮","d":"三国","role":"政治家","clues":["我年轻时隐居隆中，常把自己比作管仲、乐毅。","我为主公分析天下大势，提出联合孙权、对抗曹操的策略。","我写过《出师表》，多次率军北伐。","我是蜀汉丞相，人称“卧龙”，字孔明。"],"bio":"诸葛亮字孔明，号卧龙，三国时期蜀汉丞相，杰出的政治家、军事家。刘备三顾茅庐请他出山，他提出联吴抗曹等策略，辅佐刘备建立蜀汉。刘备死后他辅佐刘禅，多次北伐，最终病逝于五丈原军中。","quote":"非淡泊无以明志，非宁静无以致远。"},
  {"n":"曹操","d":"三国","role":"政治家","clues":["我写过“东临碣石，以观沧海”这样的诗句。","我把汉献帝迎到许县，“挟天子以令诸侯”。","官渡之战中，我以少胜多打败袁绍，统一了北方。","我在赤壁之战中被孙刘联军打败，我的儿子曹丕后来建立了魏国。"],"bio":"曹操是东汉末年杰出的政治家、军事家和文学家。他挟天子以令诸侯，在官渡之战中以少胜多打败袁绍，统一北方。208年赤壁之战失利，形成三国鼎立的基础。他的儿子曹丕于220年建立魏国，追尊他为魏武帝。","quote":"老骥伏枥，志在千里。"},
  {"n":"刘备","d":"三国","role":"皇帝","clues":["我自称是汉朝皇族的后代，早年靠卖草鞋、织席为生。","小说里说我和两位好兄弟在桃园结义。","我三次拜访隆中，请出了一位杰出的谋士。","221年，我在成都称帝，建立了蜀汉。"],"bio":"刘备字玄德，三国时期蜀汉的建立者。他自称汉朝皇族后代，早年家贫，以织席贩履为生。他三顾茅庐请出诸葛亮，联合孙权在赤壁之战中打败曹操，后来占据益州，221年在成都称帝，史称蜀或蜀汉。","quote":"勿以恶小而为之，勿以善小而不为。"},
  {"n":"关羽","d":"三国","role":"军事家","clues":["我曾在白马之战中斩杀袁绍的大将颜良。","我跟随刘备多年，后来镇守荆州。","史书记载我刮骨疗毒时仍能谈笑自若。","我字云长，红脸长须，后世尊称我为“武圣”。"],"bio":"关羽字云长，三国时期蜀汉名将。他长期追随刘备，曾在白马之战中斩杀袁绍大将颜良。后来他镇守荆州，水淹七军，威震华夏，最终因东吴袭取荆州而遇害。后世把他视为忠义的象征，尊为“武圣”。","quote":""},
  {"n":"祖冲之","d":"南北朝","role":"科学家","clues":["我编制了《大明历》，第一次把“岁差”引进历法。","我和儿子一起研究过球体积的计算方法。","我把圆周率精确到了小数点后第七位。","我算出圆周率在3.1415926和3.1415927之间，领先世界近一千年。"],"bio":"祖冲之是南朝杰出的数学家、天文学家。他计算出圆周率在3.1415926与3.1415927之间，精确到小数点后第七位，领先世界近千年。他编制的《大明历》首次引入“岁差”，使历法更加精确。","quote":""},
  {"n":"王羲之","d":"东晋","role":"书法家","clues":["相传我练字后常在池塘里洗笔，把池水都染黑了。","我特别喜欢鹅，据说还曾写字换鹅。","我和朋友在会稽山阴的兰亭聚会，写下了一篇序文。","我是东晋书法家，被尊为“书圣”。"],"bio":"王羲之是东晋著名书法家，被誉为“书圣”。他博采众长，形成了飘逸秀美的书风。353年，他与友人在兰亭聚会，写下《兰亭集序》，被誉为“天下第一行书”。他的儿子王献之也是书法家，父子并称“二王”。","quote":"后之视今，亦犹今之视昔。"},
  {"n":"花木兰","d":"南北朝","role":"传说英雄","clues":["我的故事来自北朝民歌，是不是真有其人一直有争论。","“唧唧复唧唧”，我原本坐在家门口织布。","我在军中多年，同伴们都不知道我是女孩子。","父亲年老，我女扮男装替父从军。"],"bio":"花木兰是北朝民歌《木兰诗》中的传说人物，并非有确切史料记载的真实人物。诗中她女扮男装、替父从军，征战多年立下战功，却不要官职，只愿回家与亲人团聚。她是勇敢和孝顺的象征。","quote":"雄兔脚扑朔，雌兔眼迷离；双兔傍地走，安能辨我是雄雌？"},
  {"n":"隋文帝","d":"隋","role":"皇帝","clues":["我原是北周的大臣，女儿是北周的皇后。","我开始用分科考试的办法选拔官员。","589年，我派兵灭掉南方的陈朝，结束了长期分裂的局面。","我叫杨坚，581年建立了隋朝。"],"bio":"隋文帝杨坚原是北周重臣，581年夺取北周政权，建立隋朝，定都长安。589年隋灭陈，结束了近三百年的分裂局面。他改革制度，开始用分科考试选拔官员，隋初经济繁荣，史称“开皇之治”。","quote":""},
  {"n":"隋炀帝","d":"隋","role":"皇帝","clues":["我的年号是“大业”。","我设立了进士科，标志着科举制正式诞生。","我下令开通以洛阳为中心、北抵涿郡、南达余杭的大运河。","我叫杨广，是隋朝第二位皇帝，因暴政导致隋朝灭亡。"],"bio":"隋炀帝杨广是隋朝第二位皇帝。他开通大运河，加强了南北交通；设立进士科，标志着科举制正式诞生。但他滥用民力，三征高句丽，徭役繁重，激起农民起义。618年他在江都被部下所杀，隋朝灭亡。","quote":""},
  {"n":"唐太宗","d":"唐","role":"皇帝","clues":["玄武门之变后，我成为太子，不久继承了皇位。","我说过“以铜为镜，可以正衣冠；以人为镜，可以明得失”。","西北各族尊称我为“天可汗”。","我叫李世民，我统治的时期被称为“贞观之治”。"],"bio":"唐太宗李世民是唐朝第二位皇帝。他吸取隋亡教训，虚心纳谏，重用魏征等贤臣，减轻百姓负担，完善科举制度。他统治时期政治清明、经济发展，史称“贞观之治”。他还被西北各族尊为“天可汗”。","quote":"以铜为镜，可以正衣冠；以人为镜，可以明得失。"},
  {"n":"武则天","d":"唐","role":"皇帝","clues":["我给自己造了一个新字“曌”作为名字。","我首创了殿试和武举。","我把国号改为“周”。","我是中国历史上唯一的正统女皇帝。"],"bio":"武则天是中国历史上唯一的正统女皇帝，690年改国号为周。她重视发展农业，破格任用人才，首创殿试和武举，使社会经济继续发展，为后来的“开元盛世”奠定了基础。晚年唐中宗复位，恢复唐的国号。","quote":""},
  {"n":"玄奘","d":"唐","role":"高僧","clues":["我出发时没有得到朝廷允许，偷偷越过边关西行。","我在天竺的那烂陀寺学习佛法多年。","回国后，我口述完成了《大唐西域记》。","我西行天竺取经，《西游记》里的“唐僧”就是以我为原型的。"],"bio":"玄奘是唐朝高僧。唐太宗贞观初年，他从长安出发，历经艰险到达天竺，在那烂陀寺学习佛法，645年带回大量佛经。他翻译佛经一千多卷，并口述完成《大唐西域记》。小说《西游记》中唐僧的原型就是他。","quote":""},
  {"n":"鉴真","d":"唐","role":"高僧","clues":["我是扬州大明寺的高僧。","我前五次渡海都失败了，还因此双目失明。","我在日本主持修建了唐招提寺，还传授医药知识。","我六次东渡，终于到达了日本。"],"bio":"鉴真是唐朝高僧，扬州人。他应邀东渡日本传法，前五次都失败了，还双目失明，但毫不动摇，第六次东渡终于成功。他在日本传播佛学，主持修建唐招提寺，还把中国的建筑、雕塑、医药等知识带到日本。","quote":""},
  {"n":"李白","d":"唐","role":"文学家","clues":["我自号“青莲居士”，传说出生在西域的碎叶城。","据说贺知章读了我的诗，称我为“谪仙人”。","我写过“飞流直下三千尺，疑是银河落九天”。","我是唐代浪漫主义诗人，被称为“诗仙”，写过《静夜思》。"],"bio":"李白字太白，号青莲居士，唐代伟大的浪漫主义诗人，被誉为“诗仙”。他的诗想象丰富、气势豪放，代表作有《蜀道难》《将进酒》《望庐山瀑布》等。他与杜甫并称“李杜”。","quote":"天生我材必有用，千金散尽还复来。"},
  {"n":"杜甫","d":"唐","role":"文学家","clues":["我在成都住过一座草堂，今天那里成了纪念馆。","我写过“三吏”“三别”，记录了百姓的苦难。","我的诗反映了安史之乱前后的社会现实，被称为“诗史”。","我是唐代现实主义诗人，被尊为“诗圣”。"],"bio":"杜甫字子美，唐代伟大的现实主义诗人，被尊为“诗圣”。他经历了唐朝由盛转衰的过程，写下《春望》《茅屋为秋风所破歌》和“三吏”“三别”等名篇，真实反映社会现实，他的诗被称为“诗史”。","quote":"安得广厦千万间，大庇天下寒士俱欢颜！"},
  {"n":"文成公主","d":"唐","role":"友好使者","clues":["我出发时带去了许多谷物种子、医药书籍和工匠。","相传拉萨大昭寺里的一尊释迦牟尼像是我带去的。","641年，我从长安出发，远嫁到青藏高原。","我嫁给了吐蕃赞普松赞干布，促进了唐蕃友好。"],"bio":"文成公主是唐朝宗室女。641年，唐太宗将她嫁给吐蕃赞普松赞干布。她入藏时带去了谷物种子、医药、历法和各种工匠，促进了吐蕃经济文化的发展，加深了汉藏两族人民的友谊。","quote":""},
  {"n":"赵匡胤","d":"北宋","role":"皇帝","clues":["我原来是后周的禁军统帅。","我设宴请大将们喝酒，劝他们交出兵权。","960年，部下在陈桥驿把黄袍披在了我身上。","我建立了北宋，定都东京开封，是宋太祖。"],"bio":"赵匡胤原是后周禁军统帅。960年他发动陈桥兵变，黄袍加身，建立宋朝，史称北宋，定都东京（开封）。为防止武将夺权，他通过“杯酒释兵权”解除大将兵权，并重文轻武，加强中央集权。","quote":""},
  {"n":"岳飞","d":"南宋","role":"民族英雄","clues":["我出身农家，从小刻苦习武，喜欢读兵书。","我的军队纪律严明，“冻死不拆屋，饿死不掳掠”。","我在郾城大败金军，金军感叹“撼山易，撼……家军难”。","相传母亲在我背上刺了“精忠报国”四个字。"],"bio":"岳飞是南宋抗金名将、民族英雄。他率领的岳家军纪律严明、作战勇敢，1140年在郾城大败金军，金军哀叹“撼山易，撼岳家军难”。正当他准备收复失地时，却被宋高宗和秦桧以“莫须有”的罪名杀害。","quote":"三十功名尘与土，八千里路云和月。"},
  {"n":"包拯","d":"北宋","role":"政治家","clues":["我考中进士后，为了照顾年迈的父母，多年没有去外地做官。","我在盛产砚台的端州做官，离任时连一方砚台都没有带走。","我担任过开封府知府，执法严明，不畏权贵。","民间叫我“包青天”，戏曲里常把我画成黑脸。"],"bio":"包拯是北宋名臣，庐州合肥人。他为官清廉、刚正不阿，在端州任职期满时“不持一砚归”。担任开封府知府时，他执法严峻，不徇私情，京城有“关节不到，有阎罗包老”的说法。民间尊称他为“包青天”。","quote":""},
  {"n":"毕昇","d":"北宋","role":"发明家","clues":["我是北宋的一名普通工匠，史书上对我的生平记载很少。","我用胶泥刻字，每字一印，再用火烧硬。","我的发明被沈括记录在《梦溪笔谈》里。","我发明了活字印刷术。"],"bio":"毕昇是北宋平民工匠。他在11世纪中期发明了泥活字印刷术：用胶泥刻字、火烧变硬，排版印刷，印完还可拆下重复使用，比雕版印刷省时省力。这项发明比欧洲早约400年，事迹记录在沈括的《梦溪笔谈》中。","quote":""},
  {"n":"沈括","d":"北宋","role":"科学家","clues":["我参与过王安石变法，还出使过辽国。","我给一种黑色的液体取名“石油”，预言它将“大行于世”。","我记录了指南针“常微偏东，不全南也”的现象。","我晚年住在润州梦溪园，写下了《梦溪笔谈》。"],"bio":"沈括是北宋科学家、政治家，博学多才，涉猎天文、地理、数学、医学等领域。他在《梦溪笔谈》中记载了毕昇的活字印刷术，记述了指南针的磁偏角现象，还给“石油”命名。这本书被誉为“中国科学史上的里程碑”。","quote":""},
  {"n":"苏轼","d":"北宋","role":"文学家","clues":["我在杭州做官时疏浚西湖，还筑起一条长堤。","有一道用猪肉做的名菜相传以我的号命名。","我写过“横看成岭侧成峰，远近高低各不同”。","我号东坡居士，和父亲、弟弟并称“三苏”。"],"bio":"苏轼字子瞻，号东坡居士，北宋文学家、书画家，“唐宋八大家”之一，与父亲苏洵、弟弟苏辙合称“三苏”。他的诗词豪放洒脱，代表作有《水调歌头·明月几时有》《念奴娇·赤壁怀古》等。他一生多次被贬，却始终乐观豁达。","quote":"但愿人长久，千里共婵娟。"},
  {"n":"文天祥","d":"南宋","role":"民族英雄","clues":["我二十岁左右就考中了状元。","元军南下时，我变卖家产，组织军队抗元。","我被俘后在狱中写下《正气歌》，始终拒绝投降。","我写下了“人生自古谁无死，留取丹心照汗青”。"],"bio":"文天祥是南宋末年的政治家、文学家、民族英雄。元军南下时，他起兵抗元，后来兵败被俘。元朝多次劝降，他坚贞不屈，在狱中写下《正气歌》，最后在大都英勇就义。他的《过零丁洋》表现了崇高的民族气节。","quote":"人生自古谁无死，留取丹心照汗青。"},
  {"n":"成吉思汗","d":"元","role":"蒙古大汗","clues":["我小时候父亲被敌人毒死，家境一度十分艰难。","我建立了强大的骑兵，多次向西征战。","1206年，我统一了蒙古各部，建立蒙古政权。","我的名字叫铁木真，被称为“一代天骄”。"],"bio":"成吉思汗名铁木真，是蒙古族杰出的首领。1206年他统一蒙古各部，建立蒙古政权，被尊为“成吉思汗”。此后蒙古军队不断扩张，为后来元朝的统一奠定了基础。元朝建立后，他被追尊为元太祖。","quote":""},
  {"n":"忽必烈","d":"元","role":"皇帝","clues":["我的祖父是蒙古的“一代天骄”。","我在地方设立行省，这一制度影响到今天。","1276年，我的军队攻占了南宋都城临安。","1271年，我定国号为“元”，第二年定都大都。"],"bio":"忽必烈是成吉思汗的孙子，元朝的建立者，即元世祖。1271年他定国号为元，次年定都大都（今北京）。1276年元军攻占临安，1279年消灭南宋残余势力，完成统一。他实行行省制度，设宣政院管辖西藏。","quote":""},
  {"n":"郭守敬","d":"元","role":"科学家","clues":["我也是水利专家，主持开凿了大都的通惠河。","我创制了简仪等十几种天文仪器。","我主持了大规模的天文测量“四海测验”。","我参与编订的《授时历》，一年的长度和今天的公历相同。"],"bio":"郭守敬是元朝杰出的天文学家、水利学家。他创制简仪、高表等十几种天文仪器，主持“四海测验”。他与王恂等人编订《授时历》，确定一年为365.2425天，与现行公历相同，却比公历早约300年。他还主持开凿了通惠河。","quote":""},
  {"n":"马可·波罗","d":"元","role":"旅行家","clues":["我跟随父亲和叔叔，沿着丝绸之路向东而来。","我在元朝生活了约17年，据说受到了忽必烈的信任。","回国后，我在监狱里口述了一部游记。","我是意大利威尼斯人，我的游记让欧洲人对中国充满向往。"],"bio":"马可·波罗是意大利威尼斯的商人、旅行家。元朝时他随父亲和叔叔来到中国，在中国生活了约17年。回国后他在狱中口述，由他人写成《马可·波罗行纪》，书中描述了中国的富庶，激发了欧洲人对东方的向往。","quote":""},
  {"n":"朱元璋","d":"明","role":"皇帝","clues":["我小时候给地主放过牛，还当过和尚。","我接受了“高筑墙，广积粮，缓称王”的建议。","我废除了丞相，由皇帝直接管理六部。","1368年，我在南京称帝，建立明朝，年号洪武。"],"bio":"朱元璋出身贫苦，放过牛、当过和尚，后来参加元末农民起义。1368年他在应天（今南京）称帝，建立明朝，年号洪武，同年攻占大都，推翻元朝统治。他废除丞相，权分六部，设立锦衣卫，大大强化了皇权。","quote":""},
  {"n":"郑和","d":"明","role":"航海家","clues":["我小时候姓马，后来被皇帝赐了新的姓。","我率领的船队有两百多艘海船、两万七千多人。","从1405年到1433年，我先后七次出海远航。","我奉明成祖之命下西洋，最远到达非洲东海岸和红海沿岸。"],"bio":"郑和本姓马，明朝杰出的航海家。1405年到1433年，他率领庞大船队七次下西洋，访问了亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸。郑和下西洋比哥伦布远航美洲早87年，是世界航海史上的壮举。","quote":""},
  {"n":"戚继光","d":"明","role":"民族英雄","clues":["我写了兵书《纪效新书》和《练兵实纪》。","我创造了适合南方作战的“鸳鸯阵”。","我在浙江台州九战九捷，大败倭寇。","我训练的“戚家军”是著名的抗倭队伍。"],"bio":"戚继光是明朝抗倭名将、民族英雄。16世纪中期倭寇侵扰东南沿海，他招募农民、矿工组建戚家军，纪律严明、作战勇敢，在台州等地多次大败倭寇，与俞大猷等人一起基本平定东南倭患。后来他又镇守北方边防。","quote":"封侯非我意，但愿海波平。"},
  {"n":"李时珍","d":"明","role":"医学家","clues":["我的父亲也是一名医生。","我走遍名山大川，亲自采药、尝药，花了近三十年写书。","我的书收录了1800多种药物、一万多个药方。","我写了《本草纲目》，被誉为“东方药物巨典”。"],"bio":"李时珍是明朝杰出的医药学家。他发现旧的本草书有很多错误，于是走访各地、亲自采药，参考八百多种书籍，历时近三十年写成《本草纲目》。全书收录药物1892种，被誉为“东方药物巨典”，对世界医药学影响很大。","quote":""},
  {"n":"徐霞客","d":"明","role":"旅行家","clues":["我从小喜欢读地理书，不愿参加科举考试。","我三十多年间走遍了大半个中国，常常风餐露宿。","我对石灰岩地貌的考察，比欧洲早了约两个世纪。","我的游记开篇那天——5月19日，被定为“中国旅游日”。"],"bio":"徐霞客是明朝杰出的地理学家、旅行家。他三十多年间游历了大半个中国，考察山川、河流和地貌，对石灰岩地貌的考察比欧洲早约两个世纪。他的考察日记被整理成《徐霞客游记》，游记开篇日5月19日被定为“中国旅游日”。","quote":""},
  {"n":"宋应星","d":"明","role":"科学家","clues":["我考中过举人，但多次考进士都没有成功。","我在江西分宜县做过教谕，利用业余时间写书。","我的书配有很多插图，记录了农业和手工业的生产技术。","我写了《天工开物》，被称为“中国17世纪的工艺百科全书”。"],"bio":"宋应星是明朝末年的科学家。他考进士屡次落第，转而关注农业和手工业生产技术。1637年他写成《天工开物》，系统总结了农业、手工业的生产经验，并配有大量插图，被外国学者称为“中国17世纪的工艺百科全书”。","quote":""},
  {"n":"郑成功","d":"清","role":"民族英雄","clues":["我的母亲是日本人，我出生在日本平户。","我曾被南明皇帝赐姓“朱”，人称“国姓爷”。","我以厦门、金门为基地，率领军队抗清。","1662年，我从荷兰殖民者手中收复了台湾。"],"bio":"郑成功是明末清初的民族英雄。1661年，他率领战船从金门出发，横渡台湾海峡，经过激战，1662年迫使荷兰殖民者投降，收复台湾。之后他在台湾设立府县，发展生产，促进了台湾的开发。","quote":""},
  {"n":"康熙","d":"清","role":"皇帝","clues":["我八岁登上皇位，在位61年，是中国历史上在位时间最长的皇帝。","我亲政后智擒鳌拜，又平定了三藩之乱。","我指挥雅克萨之战，与俄国签订了《尼布楚条约》。","我叫玄烨，我和孙子统治的时期被合称为“康乾盛世”。"],"bio":"康熙帝玄烨是清朝入关后的第二位皇帝，在位61年，是中国历史上在位时间最长的皇帝。他平定三藩之乱，1684年设台湾府，指挥雅克萨之战抗击沙俄，1689年与俄国签订《尼布楚条约》，开启了“康乾盛世”。","quote":""},
  {"n":"乾隆","d":"清","role":"皇帝","clues":["我在位60年后，把皇位传给儿子，自己做了太上皇。","我下令编纂了大型丛书《四库全书》。","我曾六次南巡江南。","我叫弘历，是康熙皇帝的孙子。"],"bio":"乾隆帝弘历是清朝入关后的第四位皇帝，在位60年，退位后又当了三年多太上皇。他平定大小和卓叛乱，设伊犁将军，巩固了西北边疆；又组织编纂《四库全书》。但他晚年奢侈，实行闭关锁国，清朝开始由盛转衰。","quote":""},
  {"n":"林则徐","d":"清","role":"民族英雄","clues":["我在湖广总督任上就开始严禁鸦片，成效显著。","我组织人翻译外国书报，编成《四洲志》，被称为“开眼看世界的第一人”。","我写过“苟利国家生死以，岂因祸福避趋之”。","1839年，我在虎门海滩当众销毁鸦片。"],"bio":"林则徐是清朝后期的政治家、民族英雄。1839年他作为钦差大臣到广东禁烟，在虎门海滩当众销毁收缴的鸦片二百多万斤，这就是“虎门销烟”。他还组织翻译外国书报，被誉为近代中国“开眼看世界的第一人”。","quote":"苟利国家生死以，岂因祸福避趋之。"},
  {"n":"詹天佑","d":"清","role":"工程师","clues":["我十二岁左右就作为留美幼童，远渡重洋去美国学习。","我在耶鲁大学学习土木工程和铁路。","修铁路时我设计了“人”字形线路，解决了火车爬陡坡的难题。","我主持修建了中国人自行设计的第一条干线铁路——京张铁路。"],"bio":"詹天佑是中国近代杰出的铁路工程师，被誉为“中国铁路之父”。他幼年留学美国，学习土木工程。1905年至1909年，他主持修建京张铁路，巧妙设计“人”字形线路，提前完工，这是中国人自行设计和施工的第一条干线铁路。","quote":""},
  {"n":"孙中山","d":"清","role":"革命家","clues":["我原本是一名医生，后来决心弃医从政、救国救民。","1894年，我在檀香山建立了兴中会。","我提出了“民族、民权、民生”三民主义。","我领导辛亥革命推翻清朝统治，被尊为“中国革命的先行者”。"],"bio":"孙中山名文，号逸仙，是伟大的民主革命先驱。1894年他创立兴中会，1905年成立中国同盟会，提出三民主义。1911年辛亥革命爆发，1912年1月1日他在南京就任中华民国临时大总统。同年2月清帝退位。","quote":"天下为公。"},
  {"n":"管仲","d":"春秋","role":"政治家","clues":["我年轻时和好朋友鲍叔牙一起做生意，他总是让着我。","我曾经一箭射中后来的国君的衣带钩。","好友鲍叔牙推荐我当上了齐国的相。","我辅佐齐桓公改革，使他成为春秋第一位霸主。"],"bio":"管仲是春秋时期齐国著名政治家。他曾辅佐公子纠，射中过公子小白（后来的齐桓公）。好友鲍叔牙举荐他为相，他在齐国推行改革，发展经济，使齐国强大起来，帮助齐桓公成为春秋第一位霸主。“管鲍之交”成为友谊佳话。","quote":"仓廪实而知礼节，衣食足而知荣辱。"},
  {"n":"商鞅","d":"战国","role":"政治家","clues":["我原是卫国人，后来到了秦国。","我在城门立了一根木头，说谁把它搬走就给重赏。","我推行变法，奖励耕战，建立县制。","我在秦孝公支持下变法，使秦国成为最强大的诸侯国。"],"bio":"商鞅是战国时期政治家、法家代表人物。公元前356年起，他在秦孝公支持下实行变法：承认土地私有、奖励耕战、建立县制等，并“立木为信”取信于民。变法使秦国逐渐富强，为后来秦统一六国奠定了基础。","quote":""},
  {"n":"勾践","d":"春秋","role":"君主","clues":["我曾经战败，到敌国当了三年奴仆。","我身边有两位得力谋臣：范蠡和文种。","我每天睡在柴草上，吃饭前还要尝一尝苦胆。","我是越国的国君，我的一把青铜剑两千多年后出土时依然锋利。"],"bio":"勾践是春秋末期越国国君。他被吴国打败后，到吴国为奴三年。回国后他卧薪尝胆，任用范蠡、文种，发展生产、训练军队，最终灭掉吴国，成为春秋末期的霸主。1965年出土的越王勾践剑至今仍然锋利。","quote":""},
  {"n":"卫青","d":"西汉","role":"军事家","clues":["我小时候曾经放过羊，出身十分低微。","我的姐姐进宫后成为了汉武帝的皇后。","我多次出击匈奴，收复了河套地区。","我是汉武帝时的大将军，我的外甥霍去病也是一代名将。"],"bio":"卫青是西汉著名军事家。他出身低微，因姐姐卫子夫入宫而受到汉武帝重用。他多次率军出击匈奴，收复河套地区，并在漠北之战中大败匈奴单于，官至大司马大将军，为解除匈奴威胁立下大功。","quote":""},
  {"n":"霍去病","d":"西汉","role":"军事家","clues":["我十几岁第一次随军出征，就被封为“冠军侯”。","我两次出击河西，打通了通往西域的道路。","我追击匈奴到狼居胥山，留下“封狼居胥”的典故。","我说过“匈奴未灭，何以家为”。"],"bio":"霍去病是西汉名将，卫青的外甥。他十几岁随军出征，勇冠三军，被封为冠军侯。他两次出击河西，使汉朝控制了河西走廊；漠北之战中追击匈奴到狼居胥山。他二十多岁就去世了，汉武帝为他修建了形似祁连山的坟墓。","quote":"匈奴未灭，何以家为？"},
  {"n":"班超","d":"东汉","role":"外交家","clues":["我原本在官府里抄写文书，后来“投笔从戎”。","我的哥哥编写了史书《汉书》。","我在西域经营了三十多年，还派甘英出使大秦。","我说过“不入虎穴，焉得虎子”。"],"bio":"班超是东汉著名外交家、军事家，史学家班固的弟弟。他投笔从戎，出使西域，在西域经营三十一年，帮助西域各国摆脱匈奴控制，被任命为西域都护。97年他派甘英出使大秦（罗马帝国），甘英到达了波斯湾一带。","quote":"不入虎穴，焉得虎子。"},
  {"n":"张仲景","d":"东汉","role":"医学家","clues":["相传我当长沙太守时，曾在大堂上为百姓看病。","相传我用羊肉和药材做成“娇耳”给百姓治冻伤，后来演变成饺子。","我写了《伤寒杂病论》，确立了“辨证论治”的原则。","我是东汉末年的名医，被后人尊为“医圣”。"],"bio":"张仲景是东汉末年著名医学家，被尊为“医圣”。当时瘟疫流行，他“勤求古训，博采众方”，写成《伤寒杂病论》，确立了辨证论治的原则，成为中医临床的基本原则。民间还流传着他发明饺子的传说。","quote":"勤求古训，博采众方。"},
  {"n":"贾思勰","d":"南北朝","role":"农学家","clues":["我在北魏做过太守，到过很多地方考察农业。","我向老农请教，总结了种庄稼、养牲畜、酿酒做醋的方法。","我的书名意思是“使百姓生活富足的重要方法”。","我写了《齐民要术》，这是我国现存最早最完整的农书。"],"bio":"贾思勰是北魏杰出的农学家，曾任高阳太守。他搜集古书资料，走访老农，总结了黄河中下游地区的农牧业生产经验，写成《齐民要术》。这是我国现存最早、最完整的一部农书，内容包括农作物栽培、家畜饲养、农产品加工等。","quote":""},
  {"n":"魏征","d":"唐","role":"政治家","clues":["我原来是太子李建成的手下。","我一生向皇帝进谏两百多次。","我去世后，皇帝说自己失去了一面“镜子”。","我是唐太宗时敢于直言进谏的大臣，说过“兼听则明，偏信则暗”。"],"bio":"魏征是唐初政治家，以敢于直言进谏闻名。他原是太子李建成的属官，唐太宗不计前嫌重用他。他先后进谏二百多次，劝太宗“居安思危”“兼听则明”。他去世后，太宗感叹失去了一面可以“明得失”的镜子。","quote":"兼听则明，偏信则暗。"},
  {"n":"范仲淹","d":"北宋","role":"政治家","clues":["我少年时家境贫寒，在寺庙里苦读，把一锅粥划成几块分着吃。","我曾在西北边境防御西夏。","我主持了“庆历新政”改革。","我在《岳阳楼记》中写下“先天下之忧而忧，后天下之乐而乐”。"],"bio":"范仲淹是北宋政治家、文学家。他少年家贫，刻苦读书。他曾镇守西北防御西夏，1043年主持“庆历新政”，改革吏治。他在《岳阳楼记》中写下“先天下之忧而忧，后天下之乐而乐”，体现了以天下为己任的胸怀。","quote":"先天下之忧而忧，后天下之乐而乐。"},
  {"n":"王安石","d":"北宋","role":"政治家","clues":["我是“唐宋八大家”之一。","我写过“春风又绿江南岸，明月何时照我还”。","我推行青苗法、募役法、保甲法等新法。","我在宋神宗支持下主持变法，想要富国强兵。"],"bio":"王安石是北宋政治家、文学家，“唐宋八大家”之一。1069年起，他在宋神宗支持下推行变法，实行青苗法、募役法、农田水利法、保甲法等，以求富国强兵。变法取得一定成效，但遭到保守派反对，最终失败。","quote":"春风又绿江南岸，明月何时照我还。"}
];
