GD.relics = [
  {"n":"司母戊鼎（后母戊鼎）","d":"商","type":"青铜器","c":"商朝后期铸造，1939年在河南安阳出土，重832.84千克，是迄今世界上出土的最重的青铜器。它造型雄伟，现收藏在中国国家博物馆。"},
  {"n":"四羊方尊","d":"商","type":"青铜器","c":"商朝晚期的青铜盛酒器，1938年在湖南宁乡出土。尊的四角各有一只卷角羊，羊头伸出器外，设计精巧，是商代青铜器中的杰作。"},
  {"n":"甲骨文","d":"商","type":"文字","c":"商朝人刻在龟甲和兽骨上的文字，主要记录占卜的内容，大量出土于河南安阳殷墟。它是我国已发现的最早的成熟文字，已发现的单字有四千多个。"},
  {"n":"越王勾践剑","d":"春秋","type":"青铜器","c":"1965年在湖北江陵出土，剑身刻有“越王鸠浅（勾践）自作用剑”八个鸟篆字。它在地下埋藏了两千多年，出土时依然寒光闪闪、非常锋利。"},
  {"n":"曾侯乙编钟","d":"战国","type":"乐器","c":"1978年在湖北随州曾侯乙墓出土，共65件，总重两千五百多千克。它音域宽广、音色优美，两千多年后仍能演奏乐曲，是我国迄今发现的最完整、最大的一套青铜编钟。"},
  {"n":"都江堰","d":"战国","type":"水利工程","c":"战国时期秦国蜀郡太守李冰主持修建，由鱼嘴、飞沙堰、宝瓶口等组成。它两千多年来一直发挥作用，使成都平原成为“水旱从人”的“天府之国”。"},
  {"n":"秦始皇陵兵马俑","d":"秦","type":"陶俑","c":"1974年当地农民打井时发现，是秦始皇陵的陪葬坑。陶俑和真人差不多大，神态各不相同，被誉为“世界第八大奇迹”，1987年列入《世界遗产名录》。"},
  {"n":"万里长城","d":"秦","type":"建筑","c":"长城始建于春秋战国时期，秦始皇统一后把秦、赵、燕的长城连接起来。今天看到的多是明长城，东起鸭绿江，西到嘉峪关。1987年列入《世界遗产名录》。"},
  {"n":"长信宫灯","d":"西汉","type":"青铜器","c":"1968年在河北满城汉墓出土，外形是一位跪坐持灯的宫女。灯烟可以通过宫女的袖管进入体内，减少室内污染，被称为“中华第一灯”。"},
  {"n":"金缕玉衣","d":"西汉","type":"玉器","c":"1968年在河北满城中山靖王刘胜墓出土，用两千多块玉片和约一千一百克金丝编缀而成。汉代贵族相信玉能使尸体不腐，于是用它做葬服。"},
  {"n":"马踏飞燕（铜奔马）","d":"东汉","type":"青铜器","c":"1969年在甘肃武威雷台汉墓出土。一匹骏马昂首奔腾，一只蹄子踏在飞鸟背上，平衡巧妙。1983年被定为中国旅游标志。"},
  {"n":"兰亭集序","d":"东晋","type":"书法","c":"东晋书法家王羲之353年在兰亭聚会时所写，被誉为“天下第一行书”。相传真迹随唐太宗葬入昭陵，今天流传的是唐代摹本，其中以“神龙本”最有名。"},
  {"n":"莫高窟","d":"东晋","type":"石窟","c":"位于甘肃敦煌，始凿于十六国时期的366年，历代不断开凿，唐朝最为兴盛。窟内保存着大量精美的壁画和彩塑，1987年列入《世界遗产名录》。"},
  {"n":"赵州桥","d":"隋","type":"桥梁","c":"隋朝工匠李春主持设计建造，位于河北赵县，已有1400多年历史。它是世界上现存最古老的单孔敞肩石拱桥，大拱两肩各有两个小拱，既省料又能泄洪。"},
  {"n":"大运河","d":"隋","type":"水利工程","c":"隋炀帝时开通，以洛阳为中心，北抵涿郡，南达余杭，是古代世界上最长的运河。它加强了南北交通，2014年“中国大运河”列入《世界遗产名录》。"},
  {"n":"唐三彩","d":"唐","type":"陶器","c":"唐朝盛行的一种低温釉陶器，常以黄、绿、白（或褐）等颜色为主，所以叫“三彩”。常见骆驼、马和人物造型，如著名的“三彩骆驼载乐俑”。"},
  {"n":"布达拉宫","d":"唐","type":"建筑","c":"位于西藏拉萨，相传始建于7世纪吐蕃赞普松赞干布时期，现存建筑主要是17世纪以后重建的。它依山而建、气势雄伟，1994年列入《世界遗产名录》。"},
  {"n":"清明上河图","d":"北宋","type":"绘画","c":"北宋画家张择端的作品，长五米多，描绘了北宋都城东京（开封）清明时节繁华热闹的景象，画中有八百多个人物，现收藏于北京故宫博物院。"},
  {"n":"故宫（紫禁城）","d":"明","type":"建筑","c":"明朝永乐年间修建，1420年建成，是明清两代的皇宫，先后有24位皇帝在这里居住。它是世界上现存规模最大、保存最完整的木结构宫殿建筑群。"},
  {"n":"天坛","d":"明","type":"建筑","c":"始建于1420年，是明清两代皇帝祭天、祈求五谷丰登的地方。祈年殿圆形的屋顶象征“天圆”，天坛1998年列入《世界遗产名录》。"}
];
GD.facts = (GD.facts || []).concat([
  {"cat":"历史","t":"四大发明","c":"造纸术、印刷术、指南针和火药被称为中国古代“四大发明”。它们陆续传到世界各地，对人类文明的发展产生了巨大影响，是中华民族对世界的伟大贡献。"},
  {"cat":"历史","t":"丝绸之路","c":"西汉张骞出使西域后，形成了一条从长安出发，经河西走廊、今新疆地区，到达中亚、西亚，再通往欧洲的陆上通道。中国的丝绸经这里运往西方，所以叫“丝绸之路”。"},
  {"cat":"历史","t":"郑和下西洋","c":"1405年到1433年，明朝航海家郑和率领庞大船队七次下西洋，访问了亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，比哥伦布到达美洲早87年。"},
  {"cat":"历史","t":"科举制度","c":"科举就是通过分科考试选拔官员。它创立于隋朝，唐朝逐渐完善，一直到1905年才被废除，前后延续了1300多年。殿试第一名叫“状元”。"},
  {"cat":"历史","t":"长城有多长","c":"2012年国家文物局公布，历代长城的总长度为21196.18千米，比“万里”还要长得多！其中明长城东起辽宁虎山，西到甘肃嘉峪关，是保存最完整的一段。"},
  {"cat":"历史","t":"为什么叫“华夏”","c":"炎帝、黄帝部落联盟逐渐融合形成华夏族，“夏”也和我国第一个王朝夏朝有关。古书解释说：有礼仪之大叫“夏”，有服章之美叫“华”，所以中国也称“华夏”。"},
  {"cat":"历史","t":"古人怎么计时","c":"古人把一天分成十二个时辰，每个时辰等于今天的两小时，用十二地支命名。比如“子时”是晚上11点到凌晨1点，“午时”是上午11点到下午1点。古人还用日晷、漏刻来计时。"},
  {"cat":"历史","t":"古代的“一年级”","c":"古代孩子上学常去私塾。入学时要拜孔子像，先学《三字经》《百家姓》《千字文》等启蒙读物，练习认字、写字和背诵。私塾一般只有一位先生，学生年龄大小不一。"},
  {"cat":"历史","t":"干支纪年","c":"古人用十天干（甲乙丙丁……）和十二地支（子丑寅卯……）依次搭配来纪年，六十年轮一圈，叫“六十甲子”。“甲午战争”“辛亥革命”里的“甲午”“辛亥”就是干支纪年。"},
  {"cat":"历史","t":"二十四节气","c":"二十四节气是古人根据太阳在一年中的位置变化总结出来的，用来指导农业生产，如立春、清明、夏至、冬至等。2016年，二十四节气被列入人类非物质文化遗产代表作名录。"},
  {"cat":"历史","t":"古人的名和字","c":"古人除了名，还有“字”。男子二十岁举行冠礼后取字，别人称呼他的字表示尊敬。比如李白字太白，诸葛亮字孔明，苏轼字子瞻。很多人还有“号”，如苏轼号东坡居士。"},
  {"cat":"历史","t":"年号是什么","c":"年号是皇帝用来纪年的名号。汉武帝的“建元”是中国历史上第一个年号。明清时期一个皇帝基本只用一个年号，所以人们常用“康熙”“乾隆”等年号来称呼皇帝。"},
  {"cat":"历史","t":"十二生肖","c":"十二生肖是用十二种动物和十二地支相配来纪年，如子鼠、丑牛、寅虎。最迟在东汉，王充的《论衡》中已有和今天基本一致的十二生肖记载，每十二年轮回一次。"},
  {"cat":"历史","t":"古代的“快递”","c":"古代朝廷设置驿站传递公文，驿卒骑马接力，到了驿站就换人换马。十万火急的文书要“加急”传送。唐朝时为给杨贵妃送荔枝，也用过快马接力运输。"},
  {"cat":"历史","t":"“皇帝”的由来","c":"秦王嬴政统一六国后，认为自己“德兼三皇，功过五帝”，于是创立“皇帝”称号，自称“始皇帝”。从此直到1912年清帝退位，“皇帝”这个称号在中国用了两千多年。"},
  {"cat":"历史","t":"古代的钱","c":"商朝人用海贝当货币，所以“财”“货”“贵”等字都带“贝”字旁。秦始皇统一货币，推行圆形方孔的半两钱。北宋出现的“交子”是世界上最早的纸币。"},
  {"cat":"历史","t":"瓷器与China","c":"中国是瓷器的故乡。精美的瓷器通过海上丝绸之路远销世界，深受欢迎。在英语里，小写的“china”就是瓷器的意思，大写的“China”则是中国。"},
  {"cat":"历史","t":"状元、榜眼、探花","c":"科举最高一级考试是殿试，由皇帝亲自主持。殿试成绩最好的前三名分别叫状元、榜眼、探花，合称“一甲”。考中进士是古代读书人最大的荣耀之一。"},
  {"cat":"历史","t":"《百家姓》为什么赵姓第一","c":"《百家姓》大约成书于北宋初年，开头是“赵钱孙李”。因为宋朝皇帝姓赵，所以赵排第一；钱是当时吴越国国王的姓，所以排第二。它是古代孩子的识字课本。"},
  {"cat":"历史","t":"怎么读“公元前”","c":"公元纪年以传说中耶稣诞生的那年为公元1年，之前叫公元前。公元前的数字越大，年代越早：公元前2070年比公元前221年早。没有“公元0年”，公元前1年的下一年就是公元1年。"}
]);
